class Solution {
    public int majorityElement(int[] nums) {
        int n = nums.length;
        for (int i = 0; i < n; i++) {
            int count = 0;
            for (int j = 0; j < n; j++) {
                if (nums[j] == nums[i]) count++;
            }
            if (count > n / 2) return nums[i];
        }
        return -1;   // 题目保证有解，走不到这里
    }
}

import java.util.*;

class Solution {
    public int majorityElement(int[] nums) {
        int n = nums.length;
        Map<Integer, Integer> count = new HashMap<>();

        for (int x : nums) {
            int cnt = count.getOrDefault(x, 0) + 1;
            count.put(x, cnt);
            // 超过一半就是答案，可以立刻返回
            if (cnt > n / 2) return x;
        }
        return -1;   // 题目保证有解，走不到这里
    }
}

class Solution {
    public int majorityElement(int[] nums) {
        int candidate = 0;
        int count = 0;

        for (int x : nums) {
            if (count == 0) {
                // 之前的候选人都被抵消完了，换当前元素
                candidate = x;
                count = 1;
            } else if (x == candidate) {
                count++;   // 同党，票数 +1
            } else {
                count--;   // 异党，一票抵消
            }
        }
        // 题目保证多数元素存在，candidate 即为答案；
        // 若不保证，这里需要再扫一遍校验真实次数
        return candidate;
    }
}
